#!/usr/bin/env python3
import sys, os, time, struct, hashlib, hmac, zlib, binascii

VERSION = "zip-password-finder 0.10.3"

HELP_TEXT = """Find the password of protected ZIP files

Usage: executable [OPTIONS] --inputFile <inputFile>

Options:
  -i, --inputFile <inputFile>                    path to zip input file
  -w, --workers <workers>                        number of workers
  -p, --passwordDictionary <passwordDictionary>  path to a password dictionary file
  -c, --charset <charset>                        charset to use to generate password [default: lud]
      --charsetFile <charsetFile>                path to a charset file
      --minPasswordLen <minPasswordLen>          minimum password length [default: 1]
      --maxPasswordLen <maxPasswordLen>          maximum password length [default: 10]
      --fileNumber <fileNumber>                  file number in the zip archive [default: 0]
  -s, --startingPassword <startingPassword>      password to start from
  -h, --help                                     Print help
  -V, --version                                  Print version
"""

# Traditional PKZIP crypto CRC table.
_CRC_TABLE = []
for _n in range(256):
    _c = _n
    for _ in range(8):
        if _c & 1:
            _c = 0xEDB88320 ^ (_c >> 1)
        else:
            _c >>= 1
    _CRC_TABLE.append(_c & 0xffffffff)

def _crc32_update(old, c):
    return ((old >> 8) ^ _CRC_TABLE[(old ^ c) & 0xff]) & 0xffffffff

class ZipEntry:
    __slots__ = ('name','flag','comp','mtime','crc','csize','usize','extra','lhoff')
    def __init__(self, name, flag, comp, mtime, crc, csize, usize, extra, lhoff):
        self.name=name; self.flag=flag; self.comp=comp; self.mtime=mtime
        self.crc=crc; self.csize=csize; self.usize=usize; self.extra=extra; self.lhoff=lhoff

class ZipArchive:
    def __init__(self, path):
        try:
            with open(path, 'rb') as f:
                self.data = f.read()
        except Exception as e:
            raise ValueError(str(e))
        self.entries = self._parse()

    def _parse(self):
        data = self.data
        # EOCD may have a comment; search within the maximum possible EOCD span.
        start = max(0, len(data) - (65535 + 22))
        pos = data.rfind(b'PK\x05\x06', start)
        if pos < 0:
            raise ValueError('invalid Zip archive: Could not find EOCD')
        if pos + 22 > len(data):
            raise ValueError('invalid Zip archive: Invalid EOCD')
        total = struct.unpack_from('<H', data, pos + 10)[0]
        cd_off = struct.unpack_from('<I', data, pos + 16)[0]
        entries = []
        p = cd_off
        for _ in range(total):
            if p + 46 > len(data) or data[p:p+4] != b'PK\x01\x02':
                raise ValueError('invalid Zip archive: Invalid Central Directory header')
            vals = struct.unpack_from('<HHHHHHIIIHHHHHII', data, p + 4)
            flag = vals[2]; comp = vals[3]; mtime = vals[4]
            crc = vals[6]; csize = vals[7]; usize = vals[8]
            nlen = vals[9]; xlen = vals[10]; clen = vals[11]; lhoff = vals[15]
            q = p + 46
            if q + nlen + xlen + clen > len(data):
                raise ValueError('invalid Zip archive: Invalid Central Directory entry')
            rawname = data[q:q+nlen]
            try:
                if flag & (1 << 11):
                    name = rawname.decode('utf-8')
                else:
                    name = rawname.decode('cp437')
            except Exception:
                name = rawname.decode('utf-8', 'replace')
            extra = data[q+nlen:q+nlen+xlen]
            entries.append(ZipEntry(name, flag, comp, mtime, crc, csize, usize, extra, lhoff))
            p = q + nlen + xlen + clen
        return entries

    def file_data(self, e):
        data = self.data; p = e.lhoff
        if p + 30 > len(data) or data[p:p+4] != b'PK\x03\x04':
            raise ValueError('invalid Zip archive: Invalid Local File header')
        nlen = struct.unpack_from('<H', data, p + 26)[0]
        xlen = struct.unpack_from('<H', data, p + 28)[0]
        start = p + 30 + nlen + xlen
        end = start + e.csize
        if end > len(data):
            raise ValueError('invalid Zip archive: Invalid file data')
        return data[start:end]


def _extra_fields(extra):
    p = 0
    while p + 4 <= len(extra):
        hid, sz = struct.unpack_from('<HH', extra, p)
        body = extra[p+4:p+4+sz]
        if len(body) < sz:
            break
        yield hid, body
        p += 4 + sz


def _aes_info(entry):
    for hid, body in _extra_fields(entry.extra):
        if hid == 0x9901 and len(body) >= 7:
            ver = struct.unpack_from('<H', body, 0)[0]
            vendor = body[2:4]
            strength = body[4]
            actual_comp = struct.unpack_from('<H', body, 5)[0]
            return ver, vendor, strength, actual_comp
    return None


def _zipcrypto_decrypt(entry, blob, password):
    pwd = password.encode('utf-8')
    keys = [0x12345678, 0x23456789, 0x34567890]
    def update(c):
        keys[0] = _crc32_update(keys[0], c)
        keys[1] = (keys[1] + (keys[0] & 0xff)) & 0xffffffff
        keys[1] = (keys[1] * 134775813 + 1) & 0xffffffff
        keys[2] = _crc32_update(keys[2], (keys[1] >> 24) & 0xff)
    for c in pwd:
        update(c)
    out = bytearray()
    for c in blob:
        t = (keys[2] | 2) & 0xffffffff
        k = ((t * (t ^ 1)) >> 8) & 0xff
        p = c ^ k
        out.append(p)
        update(p)
    return bytes(out)


def _inflate_raw(data):
    return zlib.decompress(data, -15)


def check_password(archive, entry, password):
    if not (entry.flag & 1):
        raise RuntimeError('not encrypted')
    blob = archive.file_data(entry)
    aes = _aes_info(entry)
    if entry.comp == 99 or aes is not None:
        if aes is None:
            return False
        ver, vendor, strength, actual_comp = aes
        keylens = {1:16, 2:24, 3:32}
        saltlens = {1:8, 2:12, 3:16}
        if strength not in keylens:
            return False
        kl = keylens[strength]; sl = saltlens[strength]
        if len(blob) < sl + 2 + 10:
            return False
        salt = blob[:sl]
        stored_pv = blob[sl:sl+2]
        enc = blob[sl+2:-10]
        auth = blob[-10:]
        try:
            dk = hashlib.pbkdf2_hmac('sha1', password.encode('utf-8'), salt, 1000, 2*kl + 2)
        except UnicodeEncodeError:
            return False
        if dk[-2:] != stored_pv:
            return False
        calc = hmac.new(dk[kl:2*kl], enc, hashlib.sha1).digest()[:10]
        return hmac.compare_digest(calc, auth)

    # Traditional ZipCrypto.  Verify the header byte first, then decrypt and
    # validate CRC/size to avoid one-byte false positives.
    if len(blob) < 12:
        return False
    dec = _zipcrypto_decrypt(entry, blob, password)
    header = dec[:12]
    check = ((entry.mtime >> 8) & 0xff) if (entry.flag & 8) else ((entry.crc >> 24) & 0xff)
    if header[11] != check:
        return False
    compdata = dec[12:]
    try:
        if entry.comp == 0:
            plain = compdata
        elif entry.comp == 8:
            plain = _inflate_raw(compdata)
        else:
            # For uncommon methods, the correct header is the best available signal.
            return True
    except Exception:
        return False
    if entry.usize != 0xffffffff and len(plain) != entry.usize:
        return False
    return (binascii.crc32(plain) & 0xffffffff) == entry.crc


def format_duration_ns(ns):
    units = [('h', 3600_000_000_000), ('m', 60_000_000_000), ('s', 1_000_000_000),
             ('ms', 1_000_000), ('us', 1_000), ('ns', 1)]
    parts = []
    rem = int(ns)
    for suffix, scale in units:
        if rem >= scale:
            v, rem = divmod(rem, scale)
            parts.append(f"{v}{suffix}")
    if not parts:
        parts.append('0ns')
    return ' '.join(parts)


def print_parse_error(msg, usage='Usage: executable [OPTIONS] --inputFile <inputFile>'):
    sys.stderr.write(f"error: {msg}\n\n{usage}\n\nFor more information, try '--help'.\n")
    return 2


def parse_args(argv):
    opts = {
        'inputFile': None, 'workers': None, 'passwordDictionary': None,
        'charset': 'lud', 'charsetFile': None, 'minPasswordLen': 1,
        'maxPasswordLen': 10, 'fileNumber': 0, 'startingPassword': None,
    }
    i = 0
    value_opts = {
        '-i':'inputFile', '--inputFile':'inputFile',
        '-w':'workers', '--workers':'workers',
        '-p':'passwordDictionary', '--passwordDictionary':'passwordDictionary',
        '-c':'charset', '--charset':'charset',
        '--charsetFile':'charsetFile',
        '--minPasswordLen':'minPasswordLen', '--maxPasswordLen':'maxPasswordLen',
        '--fileNumber':'fileNumber',
        '-s':'startingPassword', '--startingPassword':'startingPassword',
    }
    int_names = {'workers','minPasswordLen','maxPasswordLen','fileNumber'}
    while i < len(argv):
        a = argv[i]
        if a in ('-h','--help'):
            print(HELP_TEXT, end='')
            sys.exit(0)
        if a in ('-V','--version'):
            print(VERSION)
            sys.exit(0)
        opt = a; val = None
        if a.startswith('--') and '=' in a:
            opt, val = a.split('=', 1)
        if opt in value_opts:
            name = value_opts[opt]
            if val is None:
                if i + 1 >= len(argv):
                    return None, print_parse_error(f"a value is required for '{opt} <{name}>' but none was supplied")
                val = argv[i+1]; i += 1
            if name in int_names:
                try:
                    # Rust's usize parser rejects leading '-' as an unexpected arg
                    # when separate, but rejects non-digits here.
                    if val.startswith('-'):
                        raise ValueError('invalid digit found in string')
                    opts[name] = int(val, 10)
                except Exception:
                    return None, parse_value_error(opt, name, val)
            else:
                opts[name] = val
            i += 1
            continue
        if a.startswith('-'):
            # clap reports negative separate values as unexpected arguments.
            return None, print_parse_error(f"unexpected argument '{a}' found")
        return None, print_parse_error(f"unexpected argument '{a}' found")
    if opts['inputFile'] is None:
        return None, print_parse_error("the following required arguments were not provided:\n  --inputFile <inputFile>", 'Usage: executable --inputFile <inputFile>')
    return opts, None


def parse_value_error(opt, name, val):
    sys.stderr.write(f"error: invalid value '{val}' for '{opt} <{name}>': invalid digit found in string\n\nFor more information, try '--help'.\n")
    return 2


def charset_from_options(opts, dictionary_mode):
    if opts['charsetFile'] is not None:
        path = opts['charsetFile']
        if not os.path.isfile(path):
            raise CliError("'charsetFile' does not exist")
        with open(path, 'r', encoding='utf-8', errors='strict', newline=None) as f:
            # The original treats a charset file as text; trailing line endings are not useful chars.
            return f.read().rstrip('\r\n')
    csopt = opts['charset']
    charset = ''
    mapping = {
        'l': 'abcdefghijklmnopqrstuvwxyz',
        'u': 'ABCDEFGHIJKLMNOPQRSTUVWXYZ',
        'd': '0123456789',
        'h': '0123456789abcdef',
        'H': '0123456789ABCDEF',
        's': ' !"#$%&\'()*+,-./:;<=>?@[\\]^_`{|}~',
    }
    for ch in csopt:
        if ch not in mapping:
            raise CliError(f"Unknown charset option '{ch}'")
        charset += mapping[ch]
    return charset

class CliError(Exception): pass


def candidate_generator(charset, min_len, max_len, starting=None):
    base = len(charset)
    if base == 0:
        return
    start_len = min_len
    start_indices = None
    if starting is not None:
        start_len = len(starting)
        index = {ch:i for i,ch in enumerate(charset)}
        start_indices = [index[ch] for ch in starting]
    for length in range(start_len, max_len + 1):
        if starting is not None and length == start_len:
            digits = start_indices[:]
        else:
            digits = [0] * length
        while True:
            yield ''.join(charset[d] for d in digits)
            pos = length - 1
            while pos >= 0:
                digits[pos] += 1
                if digits[pos] < base:
                    break
                digits[pos] = 0
                pos -= 1
            if pos < 0:
                break


def run_search(opts):
    # Validators in the observed program require regular files.
    if not os.path.isfile(opts['inputFile']):
        raise CliError("'inputFile' does not exist")
    dict_path = opts['passwordDictionary']
    if dict_path is not None and not os.path.isfile(dict_path):
        raise CliError("'passwordDictionary' does not exist")
    if opts['workers'] is not None and opts['workers'] == 0:
        raise CliError("'workers' must be positive")
    if opts['minPasswordLen'] == 0:
        raise CliError("'minPasswordLen' must be positive")
    if opts['maxPasswordLen'] == 0:
        raise CliError("'maxPasswordLen' must be positive")
    if opts['maxPasswordLen'] < opts['minPasswordLen']:
        raise CliError("'maxPasswordLen' must be equal or greater than 'minPasswordLen'")

    try:
        archive = ZipArchive(opts['inputFile'])
    except ValueError as e:
        sys.stderr.write(f"Invalid zip file error - {e}\n")
        return 1
    fn = opts['fileNumber']
    if fn < 0 or fn >= len(archive.entries):
        sys.stderr.write(f"File number not found within archive error - '{fn}'\n")
        return 1
    entry = archive.entries[fn]
    if not (entry.flag & 1):
        sys.stderr.write(f"Invalid zip file error - the selected file in the archive is not encrypted (file_number:{fn} file_name:{entry.name})\n")
        return 1

    # Build the candidate source after ZIP validation, matching the visible error priority.
    found = None
    start_ns = time.perf_counter_ns()
    if dict_path is not None:
        with open(dict_path, 'r', encoding='utf-8', errors='replace', newline=None) as f:
            for line in f:
                if line.endswith('\n'):
                    line = line[:-1]
                if line.endswith('\r'):
                    line = line[:-1]
                try:
                    if check_password(archive, entry, line):
                        found = line
                        break
                except RuntimeError:
                    raise
    else:
        charset = charset_from_options(opts, False)
        sp = opts['startingPassword']
        if sp is not None:
            if len(sp) < opts['minPasswordLen'] or len(sp) > opts['maxPasswordLen']:
                raise CliError("'startingPassword' does not respect 'max_password_len' or 'min_password_len' configuration")
            for ch in sp:
                if ch not in charset:
                    raise CliError("'startingPassword' uses characters out of the generation charset")
        for cand in candidate_generator(charset, opts['minPasswordLen'], opts['maxPasswordLen'], sp):
            try:
                if check_password(archive, entry, cand):
                    found = cand
                    break
            except RuntimeError:
                raise
    elapsed = time.perf_counter_ns() - start_ns
    print(f"Time elapsed: {format_duration_ns(elapsed)}")
    if found is None:
        print("Password not found")
    else:
        print(f"Password found:{found}")
    return 0


def main(argv):
    opts, err = parse_args(argv)
    if err is not None:
        return err
    try:
        return run_search(opts)
    except CliError as e:
        sys.stderr.write(f"CLI argument error - \"{e}\"\n")
        return 1
    except RuntimeError as e:
        sys.stderr.write(str(e) + '\n')
        return 1
    except BrokenPipeError:
        return 1

if __name__ == '__main__':
    sys.exit(main(sys.argv[1:]))
